<?php declare(strict_types=1); namespace App\Models\Pmbm; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use App\Models\AcademicYear;
class PmbmSetting extends Model { protected $guarded=[]; protected function casts():array{return ['enabled'=>'boolean','online_registration_enabled'=>'boolean','offline_registration_enabled'=>'boolean','registration_open_at'=>'datetime','registration_close_at'=>'datetime','announcement_at'=>'datetime','minimum_initial_payment_percent'=>'integer','fee_items'=>'array','schedule_items'=>'array'];} public function academicYear():BelongsTo{return $this->belongsTo(AcademicYear::class);} }
